#!/bin/bash
set -e
echo "=== Stranger Things Theme Installer ==="

if [ ! -d "frontend/src" ]; then
  echo "ERROR: Run this from inside ticket-resale/"
  exit 1
fi
mkdir -p frontend/src/pages frontend/src/components
echo "Writing files..."

echo "" | base64 --decode > frontend/src/index.css
echo "  wrote index.css"
echo "" | base64 --decode > frontend/src/pages/Home.jsx
echo "  wrote pages/Home.jsx"
echo "" | base64 --decode > frontend/src/pages/Login.jsx
echo "  wrote pages/Login.jsx"
echo "" | base64 --decode > frontend/src/pages/Signup.jsx
echo "  wrote pages/Signup.jsx"
echo "" | base64 --decode > frontend/src/pages/Dashboard.jsx
echo "  wrote pages/Dashboard.jsx"
echo "" | base64 --decode > frontend/src/pages/Listings.jsx
echo "  wrote pages/Listings.jsx"
echo "" | base64 --decode > frontend/src/pages/Sell.jsx
echo "  wrote pages/Sell.jsx"
echo "" | base64 --decode > frontend/src/pages/Admin.jsx
echo "  wrote pages/Admin.jsx"
echo "" | base64 --decode > frontend/src/pages/Analytics.jsx
echo "  wrote pages/Analytics.jsx"
echo "" | base64 --decode > frontend/src/components/Navbar.jsx
echo "  wrote components/Navbar.jsx"
echo "" | base64 --decode > frontend/src/components/Footer.jsx
echo "  wrote components/Footer.jsx"
echo "" | base64 --decode > frontend/src/components/TicketCard.jsx
echo "  wrote components/TicketCard.jsx"
echo "" | base64 --decode > frontend/src/components/UpsideDownSky.jsx
echo "  wrote components/UpsideDownSky.jsx"
echo "" | base64 --decode > frontend/src/components/VineEnergy.jsx
echo "  wrote components/VineEnergy.jsx"
echo "" | base64 --decode > frontend/src/components/WillsWall.jsx
echo "  wrote components/WillsWall.jsx"
echo "" | base64 --decode > frontend/src/components/SignalToast.jsx
echo "  wrote components/SignalToast.jsx"
echo "" | base64 --decode > frontend/src/components/DemogorgonLoader.jsx
echo "  wrote components/DemogorgonLoader.jsx"

echo ""
echo "All files written!"
echo ""
echo "Now run:"
echo "  git add ."
echo "  git commit -m \"stranger things theme — full redesign\""
echo "  git push"
